import { useEffect, useState } from 'react';
import { uploadEventBanner } from '../services/api';

const emptyEvent = { title: '', description: '', date: '', time: '', location: '', event_type: 'offline', banner_image: '', capacity: 50, registration_deadline: '', is_free: true, price: 0, status: 'upcoming', waitlist_enabled: false, is_active: true };

function eventFormValues(event) {
  if (!event) return emptyEvent;
  const date = event.date ? new Date(event.date) : null;
  return { ...emptyEvent, ...event, date: date && !Number.isNaN(date.getTime()) ? date.toISOString().slice(0, 10) : event.date || '', time: event.time?.slice(0, 5) || (date ? date.toISOString().slice(11, 16) : ''), registration_deadline: event.registration_deadline ? new Date(event.registration_deadline).toISOString().slice(0, 16) : '' };
}

export default function AdminScreen({ events, people, onCreateEvent, onUpdateEvent, onDeleteEvent, onDeletePerson, onCheckIn }) {
  const [event, setEvent] = useState(emptyEvent);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState('');
  const [qrToken, setQrToken] = useState('');
  const [checkInResult, setCheckInResult] = useState(null);
  const [checkingIn, setCheckingIn] = useState(false);

  useEffect(() => { if (editingId) setEvent(eventFormValues(events.find((item) => item.id === editingId))); }, [editingId, events]);
  function change(field, value) { setEvent((current) => ({ ...current, [field]: value })); }
  async function uploadBanner(file) { if (!file) return; setUploading(true); setUploadError(''); try { const result = await uploadEventBanner(file); change('banner_image', result.banner_image); } catch (error) { setUploadError(error.message || 'Banner upload failed. Check that the backend is running.'); } finally { setUploading(false); } }
  function cancelEdit() { setEditingId(null); setEvent(emptyEvent); }
  async function submit(eventObject) {
    eventObject.preventDefault(); setSaving(true);
    const payload = { ...event, capacity: Number(event.capacity), price: Number(event.price), is_free: Number(event.price) === 0, registration_deadline: event.registration_deadline ? new Date(event.registration_deadline).toISOString() : null };
    if (editingId) await onUpdateEvent(editingId, payload); else await onCreateEvent(payload);
    setSaving(false); cancelEdit();
  }
  async function checkInGuest(eventObject) {
    eventObject.preventDefault(); setCheckingIn(true); setCheckInResult(null);
    try { setCheckInResult(await onCheckIn(qrToken)); setQrToken(''); } catch (error) { setCheckInResult({ detail: error.message }); } finally { setCheckingIn(false); }
  }

  return <>
    <div className="screen-heading"><div><span className="section-kicker">CONTROL ROOM</span><h2>Admin console</h2><p>Create, update, and manage community events and profiles.</p></div><span className="admin-badge">{people.length} PEOPLE · {events.length} EVENTS</span></div>
    <form className="check-in-form" onSubmit={checkInGuest}><div><span className="section-kicker">DOOR DESK</span><h3>QR check-in</h3><p>Scan a member code or paste its URL to mark attendance.</p></div><div className="check-in-controls"><input aria-label="Registration QR URL" placeholder="Paste scanned QR URL" value={qrToken} onChange={(eventObject) => setQrToken(eventObject.target.value)} required /><button className="primary-button" disabled={checkingIn}>{checkingIn ? 'Checking...' : 'Mark attended'}</button></div>{checkInResult && <p className={checkInResult.detail ? 'check-in-result error' : 'check-in-result'}>{checkInResult.detail || `${checkInResult.attendee?.name} checked in for ${checkInResult.event_title}.`}</p>}</form>
    <div className="admin-layout"><form className="admin-form" onSubmit={submit}><h3>{editingId ? 'Edit event' : 'Create an event'}</h3><label>Title<input required value={event.title} onChange={(e) => change('title', e.target.value)} /></label><label>Description<textarea required value={event.description} onChange={(e) => change('description', e.target.value)} /></label><label>Date<input required type="date" value={event.date} onChange={(e) => change('date', e.target.value)} /></label><label>Start time<input required type="time" value={event.time} onChange={(e) => change('time', e.target.value)} /></label><label>Location or online link<input required value={event.location} onChange={(e) => change('location', e.target.value)} /></label><label>Event type<select value={event.event_type} onChange={(e) => change('event_type', e.target.value)}><option value="offline">Offline</option><option value="online">Online</option><option value="hybrid">Hybrid</option></select></label><label>Banner image<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => uploadBanner(e.target.files?.[0])} />{uploading && <small className="upload-status">Uploading image...</small>}{uploadError && <small className="upload-status">{uploadError}</small>}{event.banner_image && <img className="banner-preview" src={event.banner_image} alt="Event banner preview" />}</label><label>Capacity<input required type="number" min="1" value={event.capacity} onChange={(e) => change('capacity', e.target.value)} /></label><label>Registration deadline<input type="datetime-local" value={event.registration_deadline} onChange={(e) => change('registration_deadline', e.target.value)} /></label><label>Price<input type="number" min="0" step="0.01" value={event.price} onChange={(e) => change('price', e.target.value)} /></label><label>Status<select value={event.status} onChange={(e) => change('status', e.target.value)}><option value="upcoming">Upcoming</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><label className="check-field"><input type="checkbox" checked={event.waitlist_enabled} onChange={(e) => change('waitlist_enabled', e.target.checked)} /> Enable waitlist</label><label className="check-field"><input type="checkbox" checked={event.is_active} onChange={(e) => change('is_active', e.target.checked)} /> Show event publicly</label><div className="form-footer"><button className="primary-button" disabled={saving || uploading}>{saving ? 'Saving...' : editingId ? 'Save changes ↗' : 'Publish event ↗'}</button>{editingId && <button type="button" className="secondary-button" onClick={cancelEdit}>Cancel</button>}</div></form>
      <div><div className="admin-events"><h3>Published events</h3>{events.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.title}</strong><small>{item.date} · {item.location}</small></span><div className="row-actions"><button className="edit-button" onClick={() => setEditingId(item.id)}>Edit</button><button className="danger-icon" onClick={() => onDeleteEvent(item.id)} aria-label={`Delete ${item.title}`}>×</button></div></div>)}</div><div className="admin-events admin-people"><h3>People directory</h3>{people.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.name}</strong><small>Class of {item.batch_year || '—'} · {item.current_company || 'No company'}</small></span><button className="danger-icon" onClick={() => onDeletePerson(item.user_id || item.id)} aria-label={`Remove ${item.name}`}>×</button></div>)}</div></div></div>
  </>;
}
