import EventCard from './EventCard';

export default function EventsScreen({ events, registered, onRsvp, onDelete, onOpen, admin }) {
  return <><div className="screen-heading"><div><span className="section-kicker">MARK YOUR CALENDAR</span><h2>Community events</h2><p>Join reunions, conversations, and gatherings hosted by your community.</p></div>{admin && <span className="admin-badge">ADMIN MODE</span>}</div><div className="events-grid events-list">{events.map((event) => <EventCard key={event.id} event={event} registered={registered.includes(event.id)} onRsvp={onRsvp} onDelete={onDelete} onOpen={onOpen} admin={admin} />)}</div>{!events.length && <div className="empty-state">No events have been published yet.</div>}</>;
}
